import{_ as t,o as s,c as e,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"数据可视化技术全景","description":"","frontmatter":{"title":"数据可视化技术全景","outline":[2,3]},"headers":[],"relativePath":"frontend/topics/graphics/index.md","filePath":"frontend/topics/graphics/index.md","lastUpdated":1785589115000}'),i={name:"frontend/topics/graphics/index.md"};function l(r,a,d,p,o,h){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="数据可视化技术全景" tabindex="-1">数据可视化技术全景 <a class="header-anchor" href="#数据可视化技术全景" aria-label="Permalink to &quot;数据可视化技术全景&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>数据可视化不是把一组数字交给图表库，再从柱状图、折线图和饼图中挑一个。它要先确认数据代表什么、读者要完成什么判断，再用位置、长度、颜色和形状建立可解释的映射，最后保证图表在更新、交互、无障碍、测试和导出场景中仍然可信。</p><p>本分组关注“如何用图形表达数据”。SVG、Canvas、WebGL、WebGPU 的绘制原理，矩阵、动画和拾取等底层能力由相邻的“图形与交互渲染”分组负责；这里仅在技术选型和性能边界处引用它们。</p><h2 id="_1-知识地图" tabindex="-1">1. 知识地图 <a class="header-anchor" href="#_1-知识地图" aria-label="Permalink to &quot;1. 知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th><th>学完后的产出</th></tr></thead><tbody><tr><td><a href="/frontend/topics/graphics/data-visualization">数据建模与视觉编码</a></td><td>数据类型、分析任务、视觉通道、比例尺和图表类型如何对应</td><td>能从业务问题推导图表，而不是套用图表模板</td></tr><tr><td><a href="/frontend/topics/graphics/charts">图表系统与 ECharts</a></td><td>如何用配置驱动的图表库搭建可更新、可交互的业务图表</td><td>一个包含数据集、坐标系、交互、更新和销毁的完整图表</td></tr><tr><td><a href="/frontend/topics/graphics/d3">D3 与声明式可视化</a></td><td>如何把数据映射到比例尺、坐标轴和 DOM，并控制每个图形标记</td><td>一个支持数据更新的自定义 SVG 图表</td></tr><tr><td><a href="/frontend/topics/graphics/maps-geospatial">地图、GIS 与空间数据</a></td><td>经纬度、投影、GeoJSON 和地图瓦片如何共同工作</td><td>一个能够展示 GeoJSON 点数据并正确处理坐标的 Web 地图</td></tr><tr><td><a href="/frontend/topics/graphics/accessibility-testing-export">可视化无障碍、测试与导出</a></td><td>看不见图表、不能使用鼠标或需要留档时，信息如何仍然可用</td><td>文本与表格替代、键盘交互、自动化测试和导出方案</td></tr></tbody></table><h2 id="_2-一条完整的数据链路" tabindex="-1">2. 一条完整的数据链路 <a class="header-anchor" href="#_2-一条完整的数据链路" aria-label="Permalink to &quot;2. 一条完整的数据链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务问题</span></span>
<span class="line"><span>  ↓ 明确比较、趋势、分布、关系或空间任务</span></span>
<span class="line"><span>数据模型</span></span>
<span class="line"><span>  ↓ 确认粒度、维度、度量、缺失值和单位</span></span>
<span class="line"><span>视觉编码</span></span>
<span class="line"><span>  ↓ 将字段映射到位置、长度、颜色、形状等通道</span></span>
<span class="line"><span>图表实现</span></span>
<span class="line"><span>  ↓ 使用 ECharts、D3 或地图引擎完成渲染和交互</span></span>
<span class="line"><span>质量保障</span></span>
<span class="line"><span>  ↓ 验证语义、数据、无障碍、视觉结果和导出物</span></span>
<span class="line"><span>用户判断</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>链路中的任何一层都不能由下一层补救。数据粒度错误时，增加动画不会让结论正确；视觉编码具有误导性时，换用更高性能的渲染器也没有意义。</p><h2 id="_3-技术层次与选型" tabindex="-1">3. 技术层次与选型 <a class="header-anchor" href="#_3-技术层次与选型" aria-label="Permalink to &quot;3. 技术层次与选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>代表方案</th><th>适用场景</th><th>主要成本</th></tr></thead><tbody><tr><td>HTML 与 CSS</td><td>表格、进度条、微型状态视图</td><td>数据量小、语义和可访问性优先</td><td>复杂坐标和交互能力有限</td></tr><tr><td>配置型图表库</td><td>ECharts</td><td>常见业务图表、仪表盘、联动分析</td><td>超出配置模型后定制成本上升</td></tr><tr><td>数据驱动工具</td><td>D3</td><td>非标准图形、精细的数据到图形映射</td><td>需要自行管理结构、交互和生命周期</td></tr><tr><td>Web 地图引擎</td><td>MapLibre GL JS、Leaflet</td><td>瓦片地图、GeoJSON 图层、空间交互</td><td>坐标、数据源、地图服务与合规要求更复杂</td></tr><tr><td>图形渲染 API / 引擎</td><td>SVG、Canvas、WebGL、WebGPU、PixiJS、Three.js</td><td>图形编辑器、海量对象、2D/3D 场景</td><td>需要自行建立更完整的渲染和交互系统</td></tr></tbody></table><p>选择工具时先看表达模型是否匹配，再看数据规模和性能。一个有 20 个分类的柱状图不需要因为 WebGL 更新颖就改用 GPU；一个包含百万个动态点的空间图层也不适合逐个创建 SVG 元素。</p><h2 id="_4-推荐学习路径" tabindex="-1">4. 推荐学习路径 <a class="header-anchor" href="#_4-推荐学习路径" aria-label="Permalink to &quot;4. 推荐学习路径&quot;">​</a></h2><h3 id="_4-1-业务图表路线" tabindex="-1">4.1 业务图表路线 <a class="header-anchor" href="#_4-1-业务图表路线" aria-label="Permalink to &quot;4.1 业务图表路线&quot;">​</a></h3><ol><li>先学习数据建模、分析任务和视觉编码。</li><li>使用 ECharts 完成常见图表、交互和响应式更新。</li><li>补充无障碍、测试和导出，形成可交付能力。</li><li>只有标准组件无法表达需求时，再进入 D3。</li></ol><h3 id="_4-2-定制可视化路线" tabindex="-1">4.2 定制可视化路线 <a class="header-anchor" href="#_4-2-定制可视化路线" aria-label="Permalink to &quot;4.2 定制可视化路线&quot;">​</a></h3><ol><li>掌握数据类型、比例尺、坐标轴和视觉标记。</li><li>学习 D3 的数据连接与模块体系。</li><li>根据对象数量和交互复杂度，继续学习相邻分组中的 SVG、Canvas 或 WebGL。</li><li>用自动化测试验证数据语义和关键视觉状态。</li></ol><h3 id="_4-3-空间数据路线" tabindex="-1">4.3 空间数据路线 <a class="header-anchor" href="#_4-3-空间数据路线" aria-label="Permalink to &quot;4.3 空间数据路线&quot;">​</a></h3><ol><li>理解经纬度顺序、坐标参考系和投影失真。</li><li>掌握 GeoJSON 的几何类型、属性和边界。</li><li>区分栅格瓦片、矢量瓦片与客户端 GeoJSON 图层。</li><li>使用地图引擎实现图层、视口、交互和资源释放。</li></ol><h2 id="_5-与相邻分组的边界" tabindex="-1">5. 与相邻分组的边界 <a class="header-anchor" href="#_5-与相邻分组的边界" aria-label="Permalink to &quot;5. 与相邻分组的边界&quot;">​</a></h2><ul><li>本分组解释数据语义、视觉编码、图表系统和空间可视化，不重复 <a href="/frontend/topics/graphics/foundations">坐标系、向量、矩阵与颜色</a> 的图形数学。</li><li>ECharts 和 D3 文章讲库的使用模型，不展开 <a href="/frontend/topics/graphics/svg">SVG 图形系统</a> 与 <a href="/frontend/topics/graphics/canvas-2d">Canvas 2D</a> 的底层绘制 API。</li><li>大数据量图形对象的渲染瓶颈归入 <a href="/frontend/topics/graphics/performance">图形渲染性能</a>；业务指标、Web Vitals 和监控平台归入工程体系。</li><li>数据权限、接口鉴权和隐私治理仍遵循工程体系的安全要求；地图文章只补充位置数据与第三方地图服务特有的边界。</li></ul><h2 id="_6-掌握标准" tabindex="-1">6. 掌握标准 <a class="header-anchor" href="#_6-掌握标准" aria-label="Permalink to &quot;6. 掌握标准&quot;">​</a></h2><ul><li>能先写出分析任务、数据粒度和字段语义，再选择图表。</li><li>能解释位置、长度、面积、颜色和形状在感知准确度上的差异。</li><li>能使用 ECharts 或 D3 完成初始化、更新、交互、尺寸变化和销毁。</li><li>能识别坐标顺序、投影、GeoJSON 和瓦片方案中的常见错误。</li><li>能为图表提供等价文本或表格信息，并完成键盘和颜色检查。</li><li>能分别测试数据转换、图表配置、交互结果和视觉回归。</li><li>能导出清晰、可追溯且不泄露敏感数据的图片、SVG 或表格文件。</li></ul>`,23)])])}const u=t(i,[["render",l]]);export{b as __pageData,u as default};
